func lookupSessionAssignedAgentID(t *testing.T, pool *pgxpool.Pool, sessionID uuid.UUID) uuid.UUID {
	t.Helper()

	var agentID uuid.UUID
	if err := pool.QueryRow(context.Background(), `
		SELECT pt.assigned_agent_id
		FROM chat_session cs
		JOIN project_task pt ON pt.id = cs.scope_id
		WHERE cs.id = $1
	`, sessionID).Scan(&agentID); err != nil {
		t.Fatalf("lookup session assigned agent id: %v", err)
	}
	return agentID
}

func createTerminalRecoveryResumeExecutionFixture(t *testing.T, pool *pgxpool.Pool, slug string, stopReason *string) (context.Context, repo.ChatSession, repo.FlowNodeExecution, repo.ChatMessage) {
	t.Helper()

	ctx, session, execution, message := createRecoveryResumeExecutionFixture(t, pool, slug, stopReason)

	if _, err := pool.Exec(ctx, `
		UPDATE flow_node_execution
		SET status = 'abandoned',
		    completed_at = COALESCE(completed_at, now())
		WHERE id = $1
	`, execution.ID); err != nil {
		t.Fatalf("abandon recovery execution: %v", err)
	}
	if _, err := pool.Exec(ctx, `
		UPDATE project_task pt
		SET work_status = 'blocked',
		    updated_at = now()
		FROM chat_session cs
		WHERE cs.id = $1
		  AND pt.id = cs.scope_id
	`, session.ID); err != nil {
		t.Fatalf("block recovery task: %v", err)
	}

	return ctx, session, execution, message
}

func TestJobWorkerRequeueActiveExecutionSessionsWithoutTurnsSkipsSuccessfulRecoveryResumeWrite(t *testing.T) {
	pool := testdb.New(t)
	worker := New(pool, nil, Config{
		PollInterval:         time.Hour,
		StaleScanInterval:    time.Hour,
		CleanupEnqueuePeriod: time.Hour,
	})

	ctx, session, _, _ := createSuccessfulRecoveryResumeExecutionFixture(t, pool, "requeue-active-execution-skip-successful-recovery-resume")

	requeued, err := worker.RequeueActiveExecutionSessionsWithoutTurns(ctx)
	if err != nil {
		t.Fatalf("RequeueActiveExecutionSessionsWithoutTurns: %v", err)
	}
	if requeued != 0 {
		t.Fatalf("requeued sessions = %d, want 0 when recovery resume already wrote the target file", requeued)
	}

	var queuedJobs int
	if err := pool.QueryRow(ctx, `
		SELECT COUNT(*)
		FROM job_queue
		WHERE job_type = 'agent_turn'
		  AND (payload->>'session_id')::uuid = $1
		  AND status IN ('pending', 'claimed')
	`, session.ID).Scan(&queuedJobs); err != nil {
		t.Fatalf("count queued jobs: %v", err)
	}
	if queuedJobs != 0 {
		t.Fatalf("queued jobs = %d, want 0 after successful recovery write", queuedJobs)
	}
}

